Script:
FundManagement = {
		init: function(app, container, programme) {
        		 app = app|| session.app; 
        		 container = container || $(".component[name=FundManagement]"); 
           		 if(programme) {

                 }
           		else {
                	var programmeId = getQueryParameter("programmeId");
                    api.get("B2B/Bucket(" + programmeId + ")", function(prog) { FundManagement.setup(app, container, prog); });
                }
        },

        setup: function(app, container, programme) {
        		FundManagement.setupGrid(app, container, programme.Id);
                loadComponent($(".programmeInfo", container), "ProgrammeSummary", function(c) { ProgrammeSummary.init(app, $(".programmeInfo", container), programme); });
        },

        setupGrid: function(app, container, programmeId) {
			var config = {
                     endpoint: "B2B/Bucket",
               		 odataAppend: "?$filter=ParentId eq " + programmeId + " and Key eq 'Fund'"
             };

			 model.getDatasource(config, function (ds) {
                   var grid = $("[name=grid]", container).kendoGrid({
                          dataSource: ds,
                          editable: true,
                          sortable: true,
                          filterable: true,
                          scrollable: true,
                          pageable: {
                              refresh: true,
                              pageSizes: true,
                              buttonCount: 5
                          },
                          toolbar: "<button name='create'><span class='k-icon k-i-plus'></span>[resource_displayname[New]]</button>",
                          columns: [
                              { field: "Name", title: "[resource_shortdisplayname[Name]]", width: 200 },
                              { field: "Description", title: "[resource_shortdisplayname[Description]]" },
                              { width: 270, template: function (data) { return "<a href='/Funding/Contracts?fundId=" + data.Id + "'><span class='k-icon k-i-folder-open'></span>[resource_displayname[Contracts]]</a>" + 
                                      "<a name='save' class='link'><span class='k-icon k-i-save'></span>[resource_displayname[Save]]</a>" + 
                                      "<a name='destroy' class='link'><span class='k-icon k-i-delete'></span>[resource_displayname[Delete]]</a>"; }
                              }
                          ],
                          detailTemplate: kendo.template($("script[name=fundDetails]").html()),
                		  detailExpand: function(e) { FundManagement.expand(app, $(e.detailRow), this.dataItem(e.masterRow)); },
                          dataBound: function () {
                              $("a[name=save]", grid).on("click", function(e) { FundManagement.save(e, container); });
                              $("a[name=destroy]", grid).on("click", function(e) { FundManagement.destroy(e, container); });
                          }
                    });

                    $("button[name=create]", grid).on("click", function (e) { FundManagement.newBucket(e, container, programmeId); });
			  });
        },

   		expand: function(app, container, fund) {
               var tabs = $("[name=tabs]", container).kendoTabStrip({ animation: { open: { effects: "fadeIn" } } });
               loadComponent($(".tab[name=summary]", container), "FundSummary", function(c) { FundSummary.init(app, $("[name=summary]", container), fund); });
               loadComponent($(".tab[name=roles]", container), "BucketedRoleManagement", function(c) { BucketedRoleManagement.init(app, $("[name=roles]", container), fund); });
       },

   		save: function (e, container) {
           e.preventDefault();
           var grid = $("[name=grid]", container).data("kendoGrid");
           var bucket = grid.dataItem($(e.currentTarget).closest("tr"));
           bucket.save(e, function () { notification.success("[resource_displayname[BucketSaved]]"); });
       },

       destroy: function (e, container) {
           e.preventDefault();

		   var d = new ConfirmDialog({
			   question: [resource_shortdisplayname[confirmdelete]],
			   confirm:[resource_shortdisplayname[confirm]],
			   close:{resource_shortdisplayname[close]]});

			   d.events.confirm =  function () 
			   { 
               var grid = $("[name=grid]", container).data("kendoGrid");
               var bucket = grid.dataItem($(e.currentTarget).closest("tr"));
               bucket.destroy(e, function () {
                   	notification.success("[resource_description[BucketDeleted]]");
                   	var grid = $("[name=grid]", container).data("kendoGrid");
                   	grid.dataSource.read();
                   	grid.refresh();
			   }

			   d.init();
        },

   		newBucket: function(e, container, parentId) {
        		e.preventDefault();
                var newBucket = {
                        ParentId: parentId,
                		Name: "New Fund",
                    	Key: "Fund",
                   		Description: "New Fund"
                };

        		api.add("B2B/Bucket", newBucket, function(res) { 
                    notification.success("[resource_description[BucketCreated]]"); 
                    var grid = $("[name=grid]", container).data("kendoGrid");
                   	grid.dataSource.read();
                   	grid.refresh();
                });
        }
};
